// Generalization of reference/code/forest_audit.cpp from n<=8 to n<=9 vertices (L<=8 loops).
// Same atoms/forest algorithm, ordering and JSON output; class keys and atom keys are unsigned __int128
// written in decimal. Atom key = (vertex count << S) | (2 bits per vertex pair of the canonical
// relabelling) with S = max(56, n(n-1)); S = 56 for n<=8 exactly as in the reference, so for
// Lmax<=7 both JSON outputs are byte-identical to the reference. For 9-vertex atoms only the
// raw->canonical memo entry is cached (the reference caches the whole orbit; results are identical).
// Usage: forest_audit <root with classes1..Lmax.txt> <output.json> [Lmax=7] [subset_output.json]
// The optional subset output (not in the reference) lists, per L, class counts and the exact sums of
// the per-graph forest polynomials (beta: wa-weighted, gamma: wb-weighted) over selected class subsets,
// in particular power-free & articulation-point & not-exact-zero.
#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;using U=unsigned __int128;using Rat=boost::multiprecision::cpp_rational;
static string u128s(U x){if(!x)return "0";char b[48];int p=47;b[p]=0;while(x){b[--p]=char('0'+int(x%10));x/=10;}return string(b+p);}
static U readu128(istream&in){string s;if(!(in>>s)||s.empty())throw runtime_error("missing key");U x=0;for(char c:s){if(c<'0'||c>'9')throw runtime_error("bad key "+s);U y=x*10+U(c-'0');if((y-U(c-'0'))/10!=x)throw runtime_error("key overflow "+s);x=y;}return x;}
const int NV=9;
map<U,U>ccache;map<U,pair<int,int>>atominfo;
U canonical(const vector<pair<int,int>>&ed){vector<int>vs;int dm[NV]={};for(auto[a,b]:ed){vs.push_back(a);vs.push_back(b);dm[a]++;dm[b]++;}sort(vs.begin(),vs.end());vs.erase(unique(vs.begin(),vs.end()),vs.end());stable_sort(vs.begin(),vs.end(),[&](int a,int b){return dm[a]<dm[b];});int n=vs.size(),im[NV][NV]={},idx[NV];for(int i=0;i<n;i++)idx[vs[i]]=i;for(auto[a,b]:ed)im[idx[a]][idx[b]]++,im[idx[b]][idx[a]]++;const int shift=max(56,n*(n-1));auto pack=[&](const vector<int>&p){U key=U(n)<<shift;int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)key|=U(im[p[i]][p[j]])<<(2*k++);return key;};vector<int>p(n);iota(p.begin(),p.end(),0);U raw=pack(p);auto it=ccache.find(raw);if(it!=ccache.end())return it->second;vector<vector<int>>groups;for(int i=0;i<n;){vector<int>g;int j=i;while(j<n&&dm[vs[j]]==dm[vs[i]])g.push_back(j++);groups.push_back(g);i=j;}U best=raw;vector<U>orbit;function<void(int)>rec=[&](int k){if(k==(int)groups.size()){U z=pack(p);best=min(best,z);if(n<=8)orbit.push_back(z);return;}auto g=groups[k];do{for(int j=0;j<(int)g.size();j++)p[groups[k][j]]=g[j];rec(k+1);}while(next_permutation(g.begin(),g.end()));};rec(0);for(U z:orbit)ccache[z]=best;if(n>8)ccache[raw]=best;atominfo[best]={n,(int)ed.size()};return best;}
vector<U>atoms(const vector<pair<int,int>>&ed){int mask=0;for(auto[a,b]:ed)mask|=(1<<a)|(1<<b);if(!mask)return {};for(int cut=0;cut<NV;cut++)if(mask>>cut&1){int rem=mask^(1<<cut);vector<int>comps;while(rem){int s=rem&-rem;bool change=true;while(change){int old=s;for(auto[a,b]:ed)if(a!=cut&&b!=cut&&(((s>>a)&1)||((s>>b)&1)))s|=(1<<a)|(1<<b);change=s!=old;}comps.push_back(s);rem&=~s;}if(comps.size()>1){vector<U>out;for(int c:comps){int t=c|(1<<cut);vector<pair<int,int>>e;for(auto[a,b]:ed)if((t>>a&1)&&(t>>b&1))e.push_back({a,b});auto z=atoms(e);out.insert(out.end(),z.begin(),z.end());}sort(out.begin(),out.end());return out;}}return {canonical(ed)};}
bool onepi(int mask,const vector<pair<int,int>>&ed){if(__builtin_popcount((unsigned)mask)<2)return false;int low=mask&-mask;for(int s=(mask-1)&mask;s;s=(s-1)&mask){if(s&low)continue;int cross=0;for(auto[a,b]:ed)if((mask>>a&1)&&(mask>>b&1)&&((s>>a&1)!=(s>>b&1)))cross++;if(cross<2)return false;}return true;}
int findr(int*p,int a){while(a!=p[a])a=p[a];return a;}
void emitpoly(ostream&out,const map<vector<U>,Rat>&pol){out<<'[';bool first=true;for(auto&[key,v]:pol)if(v!=0){if(!first)out<<',';first=false;out<<"{\"monomial\":[";for(int j=0;j<(int)key.size();j++){if(j)out<<',';out<<'"'<<u128s(key[j])<<'"';}out<<"],\"coefficient\":\""<<v<<"\"}";}out<<']';}
// --- subset bookkeeping (new; does not influence the reference outputs) ---
bool has_articulation(int n,const vector<pair<int,int>>&ed){ // same notion as networkx.articulation_points on the simple graph with nodes 0..n-1
 auto ncomp=[&](int skip){int seen=0,c=0;for(int s=0;s<n;s++){if(s==skip||(seen>>s&1))continue;c++;int m=1<<s;bool ch=true;while(ch){int old=m;for(auto[a,b]:ed)if(a!=skip&&b!=skip&&((m>>a&1)||(m>>b&1)))m|=(1<<a)|(1<<b);ch=m!=old;}seen|=m;}return c;};
 int base=ncomp(-1);for(int c=0;c<n;c++)if(ncomp(c)>base)return true;return false;}
size_t nonzero_count(const map<vector<U>,Rat>&p){size_t k=0;for(auto&[m,v]:p)if(v!=0)k++;return k;}
struct Subset{string name;vector<int>ids;map<vector<U>,Rat>A,B;};
int main(int argc,char**argv){if(argc<3){cerr<<"usage: forest_audit root output.json [Lmax=7] [subset_output.json]\n";return 2;}
 string root=argv[1],output=argv[2];int Lmax=argc>3?atoi(argv[3]):7;if(Lmax<1||Lmax>NV-1){cerr<<"Lmax must be in 1..8\n";return 2;}string subout=argc>4?argv[4]:"";
 ofstream out(output),zero(output+".zero.json");ofstream sub;if(!subout.empty()){sub.open(subout);sub<<'{';}
 out<<'{';zero<<'{';for(int L=1;L<=Lmax;L++){if(L>1){out<<',';zero<<',';if(sub.is_open())sub<<',';}ifstream in(root+"/classes"+to_string(L)+".txt");int n,NG;in>>n>>NG;if(!in||n!=L+1){cerr<<"bad classes file for L="<<L<<'\n';return 2;}vector<pair<int,int>>pairs;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)pairs.push_back({a,b});map<vector<U>,Rat>A,B,BA,BB;vector<int>zeros;long long nf=0;
 vector<Subset>S={{"free_articulation_nonzero"},{"free_articulation"},{"free_primitive"},{"power_articulation"},{"articulation"}};long long cnt_power=0,cnt_prim=0,cnt_art=0;
 for(int gi=0;gi<NG;gi++){U key=readu128(in);long long aut,orbit;in>>aut>>orbit;int deg[NV]={},fact[]={1,1,2,6,24},ss=0;long long den=aut;vector<pair<int,int>>ed;for(int k=0;k<(int)pairs.size();k++){int m=int(key>>(2*k)&3);den*=fact[m];auto[a,b]=pairs[k];for(int j=0;j<m;j++){ed.push_back({a,b});deg[a]++;deg[b]++;}}for(int i=0;i<n;i++){den*=fact[4-deg[i]];ss+=(4-deg[i])*(3-deg[i]);}Rat wa=Rat(24)/den,wb=wa*ss/12;auto aa=atoms(ed);BA[aa]+=wa;BB[aa]+=wb;
 vector<int>subs;int full=(1<<n)-1;bool power=false;for(int s=1;s<full;s++){int v=__builtin_popcount((unsigned)s),e=0;if(v<2)continue;for(auto[a,b]:ed)if((s>>a&1)&&(s>>b&1))e++;if(e==2*(v-1)&&onepi(s,ed))subs.push_back(s);else if(sub.is_open()&&!power&&e>2*(v-1)&&onepi(s,ed))power=true;}vector<vector<bool>>comp(subs.size(),vector<bool>(subs.size()));for(int i=0;i<(int)subs.size();i++)for(int j=0;j<(int)subs.size();j++){int a=subs[i],b=subs[j];comp[i][j]=((a&b)==a)||((a&b)==b)||(__builtin_popcount((unsigned)(a&b))<=1);}vector<int>sel;map<vector<U>,long long>poly;
 auto emit=[&](){nf++;vector<int>sets;for(int j:sel)sets.push_back(subs[j]);sets.push_back(full);vector<U>as;int he=0;bool valid=true;for(int P:sets){vector<int>ch;for(int s:sets)if(s!=P&&(s&P)==s){bool mx=true;for(int z:sets)if(z!=P&&z!=s&&(z&P)==z&&(s&z)==s){mx=false;break;}if(mx)ch.push_back(s);}int par[NV];iota(par,par+NV,0);for(int s:ch){int r=__builtin_ctz((unsigned)s);for(int i=0;i<n;i++)if(s>>i&1){int a=findr(par,r),b=findr(par,i);par[max(a,b)]=min(a,b);}}vector<pair<int,int>>qe;for(auto[a,b]:ed){if(!(P>>a&1)||!(P>>b&1))continue;bool inside=false;for(int s:ch)if((s>>a&1)&&(s>>b&1)){inside=true;break;}if(inside)continue;int x=findr(par,a),y=findr(par,b);if(x==y){valid=false;break;}qe.push_back({min(x,y),max(x,y)});}if(!valid)break;if(P==full)he=qe.size()/2;auto z=atoms(qe);as.insert(as.end(),z.begin(),z.end());}if(!valid||!he)return;sort(as.begin(),as.end());poly[as]+=(sel.size()%2?-he:he);};
 function<void(vector<int>)>rec=[&](vector<int>cand){emit();for(int k=0;k<(int)cand.size();k++){int j=cand[k];sel.push_back(j);vector<int>next;for(int u=k+1;u<(int)cand.size();u++)if(comp[j][cand[u]])next.push_back(cand[u]);rec(next);sel.pop_back();}};vector<int>all(subs.size());iota(all.begin(),all.end(),0);rec(all);bool nonzero=false;
 bool art=false,prim=false;vector<Subset*>mine;if(sub.is_open()){art=has_articulation(n,ed);prim=subs.empty()&&!power;cnt_power+=power;cnt_prim+=prim;cnt_art+=art;bool flags[5]={false,!power&&art,!power&&prim,power&&art,art};for(int t=0;t<5;t++)if(flags[t])mine.push_back(&S[t]);}
 for(auto&[mon,v]:poly)if(v){nonzero=true;Rat c=v*(L%2?1:-1);A[mon]+=wa*c;B[mon]+=wb*c;for(Subset*q:mine){q->A[mon]+=wa*c;q->B[mon]+=wb*c;}if(sub.is_open()&&!power&&art){S[0].A[mon]+=wa*c;S[0].B[mon]+=wb*c;}}if(!nonzero)zeros.push_back(gi);
 if(sub.is_open()){for(Subset*q:mine)q->ids.push_back(gi);if(!power&&art&&nonzero)S[0].ids.push_back(gi);}
 if(gi%500==499)cerr<<L<<" graph "<<gi<<" cache "<<ccache.size()<<'\n';}
 out<<'"'<<L<<"\":{\"bareA\":";emitpoly(out,BA);out<<",\"bareB\":";emitpoly(out,BB);out<<",\"beta\":";emitpoly(out,A);out<<",\"gamma\":";emitpoly(out,B);out<<",\"forest_count\":"<<nf<<'}';zero<<'"'<<L<<"\":[";for(int j=0;j<(int)zeros.size();j++){if(j)zero<<',';zero<<zeros[j];}zero<<']';
 if(sub.is_open()){sub<<'"'<<L<<"\":{\"classes\":"<<NG<<",\"power_classes\":"<<cnt_power<<",\"primitive_classes\":"<<cnt_prim<<",\"articulation_classes\":"<<cnt_art<<",\"exact_zero_classes\":"<<zeros.size()<<",\"beta_monomials_all\":"<<nonzero_count(A)<<",\"gamma_monomials_all\":"<<nonzero_count(B)<<",\"subsets\":{";for(int t=0;t<5;t++){auto&q=S[t];if(t)sub<<',';size_t ka=nonzero_count(q.A),kb=nonzero_count(q.B);sub<<'"'<<q.name<<"\":{\"size\":"<<q.ids.size()<<",\"beta_monomials\":"<<ka<<",\"gamma_monomials\":"<<kb<<",\"beta_zero\":"<<(ka?"false":"true")<<",\"gamma_zero\":"<<(kb?"false":"true")<<",\"ids\":[";for(size_t j=0;j<q.ids.size();j++){if(j)sub<<',';sub<<q.ids[j];}sub<<"],\"beta\":";emitpoly(sub,q.A);sub<<",\"gamma\":";emitpoly(sub,q.B);sub<<'}';cerr<<"L "<<L<<" subset "<<q.name<<" size "<<q.ids.size()<<" beta_monomials "<<ka<<" gamma_monomials "<<kb<<'\n';}sub<<"}}";}
 cerr<<"L "<<L<<" completed graphs "<<NG<<" forests "<<nf<<" cache "<<ccache.size()<<" zero "<<zeros.size()<<'\n';}out<<'}';zero<<'}';if(sub.is_open()){sub<<'}';sub.close();if(!sub){cerr<<"subset write failed\n";return 1;}}
 out.close();zero.close();if(!out||!zero){cerr<<"write failed\n";return 1;}}
